"use client";

import { useEffect, useMemo, useState } from "react";

import Navbar from "@/components/Navbar";
import SearchBar from "@/components/SearchBar";
import CategoryBar from "@/components/CategoryBar";
import ListingGrid from "@/components/ListingGrid";

import { getListings } from "@/lib/api";

import type { Listing } from "@/lib/api";


export default function Home() {

  const [allListings, setAllListings] =
    useState<Listing[]>([]);

  const [loading, setLoading] =
    useState(true);

  const [location, setLocation] =
    useState("");

  const [selectedFilters, setSelectedFilters] =
    useState<string[]>([]);


  /* ==========================================
     LOAD ALL LISTINGS
  ========================================== */

  useEffect(() => {

    async function loadListings() {

      try {

        setLoading(true);

        const data =
          await getListings();

        setAllListings(data);

      } catch (error) {

        console.error(
          "Failed to load listings:",
          error
        );

      } finally {

        setLoading(false);

      }
    }

    loadListings();

  }, []);


  /* ==========================================
     REAL FILTERING
  ========================================== */

  const filteredListings = useMemo(() => {

    let result = [...allListings];


    /* ----------------------------------------
       LOCATION SEARCH
    ---------------------------------------- */

    if (location.trim()) {

      const search =
        location
          .trim()
          .toLowerCase();

      result = result.filter(
        (listing) => {

          const locationText =
            listing.location
              ?.toLowerCase() || "";

          const title =
            listing.title
              ?.toLowerCase() || "";

          const description =
            listing.description
              ?.toLowerCase() || "";

          return (
            locationText.includes(search) ||
            title.includes(search) ||
            description.includes(search)
          );
        }
      );
    }


    /* ----------------------------------------
       AMENITY FILTERS
    ---------------------------------------- */

    const amenityFilters =
      selectedFilters.filter(
        (filter) =>
          [
            "Washer",
            "Kitchen",
            "WiFi",
            "TV",
            "Air conditioning",
          ].includes(filter)
      );


    if (amenityFilters.length > 0) {

      result = result.filter(
        (listing) => {

          const listingAmenities =
            listing.amenities.map(
              (item) =>
                item.amenity.name
            );

          return amenityFilters.every(
            (required) =>
              listingAmenities.includes(
                required
              )
          );
        }
      );
    }


    /* ----------------------------------------
       PROPERTY TYPE
    ---------------------------------------- */

    const propertyFilters =
      selectedFilters.filter(
        (filter) =>
          filter === "home" ||
          filter === "experience" ||
          filter === "service"
      );


    if (
      propertyFilters.includes("home")
    ) {

      result = result.filter(
        (listing) =>
          [
            "House",
            "Villa",
            "Apartment",
            "Studio",
            "Penthouse",
            "Cabin",
            "Cottage",
          ].includes(
            listing.property_type
          )
      );
    }


    return result;

  }, [
    allListings,
    location,
    selectedFilters,
  ]);


  /* ==========================================
     RESULT LOCATION TITLE
  ========================================== */

  const resultTitle =
    location.trim()
      ? `Homes in ${location}`
      : "Popular homes nearby";


  return (
    <main>

      {/* NAVBAR */}

      <Navbar />


      {/* SEARCH */}

      <SearchBar
        onLocationChange={(value) => {
          setLocation(value);
        }}
      />


      {/* FILTER BAR */}

      <CategoryBar
        selectedFilters={
          selectedFilters
        }
        onFiltersChange={
          setSelectedFilters
        }
      />


      {/* CONTENT */}

      <div className="page-content">

        <div className="results-header">

          <h2>
            {loading
              ? "Finding homes..."
              : location.trim()
              ? `${filteredListings.length} homes in ${location}`
              : resultTitle}
          </h2>

          {!loading &&
            location.trim() && (
              <p>
                {filteredListings.length === 0
                  ? "No matching homes found"
                  : "Matching homes"}
              </p>
            )}

        </div>


        {/* LOADING */}

        {loading ? (

          <div className="loading-state">
            Finding the best homes for you...
          </div>

        ) : (

          <ListingGrid
            listings={
              filteredListings
            }
          />

        )}

      </div>

    </main>
  );
}