"use client";

interface CategoryBarProps {
  selectedFilters?: string[];
  onFiltersChange?: (filters: string[]) => void;
}

const categories = [
  {
    icon: "🌍",
    name: "All",
    filter: "",
  },
  {
    icon: "🏠",
    name: "Homes",
    filter: "home",
  },
  {
    icon: "🎈",
    name: "Experiences",
    filter: "experience",
  },
  {
    icon: "🛎️",
    name: "Services",
    filter: "service",
  },
];

const amenities = [
  {
    name: "Washing machine",
    filter: "Washer",
  },
  {
    name: "Kitchen",
    filter: "Kitchen",
  },
  {
    name: "Wifi",
    filter: "WiFi",
  },
  {
    name: "TV",
    filter: "TV",
  },
  {
    name: "Air conditioning",
    filter: "Air conditioning",
  },
];

export default function CategoryBar({
  selectedFilters = [],
  onFiltersChange = () => {},
}: CategoryBarProps) {

  function toggleFilter(filter: string) {
    if (!filter) {
      onFiltersChange([]);
      return;
    }

    const exists = selectedFilters.includes(filter);

    if (exists) {
      onFiltersChange(
        selectedFilters.filter(
          (item) => item !== filter
        )
      );
    } else {
      onFiltersChange([
        ...selectedFilters,
        filter,
      ]);
    }
  }

  return (
    <div className="category-wrapper">

      {/* MAIN CATEGORIES */}

      <div className="category-list">

        {categories.map((category) => {

          const active =
            category.filter === ""
              ? selectedFilters.length === 0
              : selectedFilters.includes(
                  category.filter
                );

          return (
            <button
              key={category.name}
              type="button"
              className={`category-item ${
                active
                  ? "category-item-selected"
                  : ""
              }`}
              onClick={() =>
                toggleFilter(category.filter)
              }
            >
              <span className="category-icon">
                {category.icon}
              </span>

              <span className="category-name">
                {category.name}
              </span>
            </button>
          );
        })}

      </div>


      {/* FILTER BUTTON */}

      <button
        type="button"
        className={`filter-button ${
          selectedFilters.length > 0
            ? "filter-button-active"
            : ""
        }`}
        onClick={() => {
          if (selectedFilters.length > 0) {
            onFiltersChange([]);
          }
        }}
      >
        <span className="filter-icon">
          ☷
        </span>

        <span>
          Filters
        </span>

        {selectedFilters.length > 0 && (
          <span className="filter-check">
            {selectedFilters.length}
          </span>
        )}
      </button>


      {/* AMENITY CHIPS */}

      <div className="amenity-filter-list">

        {amenities.map((item) => {

          const active =
            selectedFilters.includes(
              item.filter
            );

          return (
            <button
              key={item.name}
              type="button"
              className={`amenity-filter-chip ${
                active
                  ? "amenity-filter-chip-active"
                  : ""
              }`}
              onClick={() =>
                toggleFilter(item.filter)
              }
            >
              {item.name}

              {active && (
                <span>✓</span>
              )}
            </button>
          );
        })}

      </div>

    </div>
  );
}